void pdf_set_flag_and_debug(struct pdf_struct *pdf, struct pdf_obj *obj, enum pdf_flag flag) {
    // Set the specified flag in the PDF structure
    pdf->flags |= (1 << flag);

    // Early exit if debugging is not enabled
    if (!(pdf->flags & (1 << PDF_DEBUG_FLAG))) {
        return;
    }

    // Determine the debug message based on the flag
    const char *message = nullptr;
    switch (flag) {
        case PDF_FLAG_UNCLOSED_DICT:
            message = "Unclosed dictionary";
            break;
        case PDF_FLAG_BAD_STREAM_FILTER:
            message = "Bad stream filter";
            break;
        case PDF_FLAG_ENCRYPTED:
            message = "Object is encrypted";
            break;
        // Add additional cases as needed for other flags
        default:
            message = "Unknown flag";
            break;
    }

    // Log the debug message with the object ID
    if (message) {
        fprintf(stderr, "%s (object ID %d)\n", message, obj->id);
    }
}

void pdf_set_flag(struct pdf_struct *pdf, struct pdf_obj *obj, enum pdf_flag flag) {
    if (!pdf || !obj) {
        return;
    }

    pdf->flags |= (1 << flag);

    if (!(pdf->debug & (1 << flag))) {
        return;
    }

    const char *msg = nullptr;
    switch (flag) {
        case PDF_FLAG_UNCLOSED_DICT:
            msg = "Unclosed dictionary at object %d";
            break;
        case PDF_FLAG_BAD_STREAM_FILTER:
            msg = "Bad stream filter at object %d";
            break;
        case PDF_FLAG_ENCRYPTED:
            msg = "Object %d is encrypted";
            break;
        default:
            return;
    }

    if (msg) {
        fprintf(stderr, msg, pdf_obj_get_id(obj));
    }
}

